import{_ as t,o as n,c as r,a3 as a}from"./chunks/framework.B9qR_F1m.js";const i="/bilder/kneeboards.jpg",s="/bilder/comm-plan.jpg",b=JSON.parse('{"title":"Kneeboards & Comm Plan","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/kneeboards.md","filePath":"bereiche/kneeboards.md"}'),d={name:"bereiche/kneeboards.md"};function o(l,e,g,h,u,m){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="kneeboards-comm-plan" tabindex="-1">Kneeboards &amp; Comm Plan <a class="header-anchor" href="#kneeboards-comm-plan" aria-label="Permalink to &quot;Kneeboards &amp; Comm Plan&quot;">​</a></h1><p>Während die <a href="./lineup-card">Lineup Card</a> zu einem Flight gehört, sind die Kneeboards hier <strong>für das ganze Paket</strong>: Deckblatt, SPINS, Abnormals, Wetter, Lagekarte. Sie landen im Kneeboard aller oder ausgewählter Flugzeuge.</p><p><img src="'+i+'" alt="Bereich Kneeboards mit Deckblatt-Editor und Vorschau" loading="lazy"></p><h2 id="seiten-anlegen" tabindex="-1">Seiten anlegen <a class="header-anchor" href="#seiten-anlegen" aria-label="Permalink to &quot;Seiten anlegen&quot;">​</a></h2><p>Links unten unter <strong>Neu aus Vorlage</strong> eine Vorlage anklicken. Die Seite erscheint oben in der Liste, rechts siehst du sie, wie sie im Cockpit aussieht. Vorlagen sind mit sinnvollen, NATO-üblichen Inhalten vorbelegt – anpassen, nicht von vorn schreiben. Über <strong>Vorbelegung</strong> holst du die Standardinhalte zurück.</p><table tabindex="0"><thead><tr><th>Vorlage</th><th>Inhalt</th><th></th></tr></thead><tbody><tr><td><strong>Deckblatt</strong></td><td>Titelseite mit Foto, Einheit, Operation, Zeiten, Klassifizierung. Vier Layouts, eigenes Foto möglich.</td><td></td></tr><tr><td><strong>Auftrag / Ziele</strong></td><td>Fünf-Punkte-Befehl: Lage, Auftrag, Durchführung, Versorgung, Führung.</td><td></td></tr><tr><td><strong>SPINS</strong></td><td>Platzverfahren (Start, Rejoin, Recovery), Luftraum, ROE, ID, IFF, Tanker, CSAR.</td><td></td></tr><tr><td><strong>Abnormals</strong></td><td>Abort, NORDO, Lost Wingman, Battle Damage, Hung Ordnance, Fuel, Bird Strike, Ausstieg.</td><td></td></tr><tr><td><strong>SITREP</strong></td><td>Lagebericht zur Kampagne oder vor einer Mission.</td><td></td></tr><tr><td><strong>Codewörter</strong></td><td>Missionseigene Codewörter und wichtige Brevity-Begriffe.</td><td></td></tr><tr><td><strong>Index</strong></td><td>Erste Seite: alle Flights mit Farbe, Muster, Auftrag und Seitenzahlen.</td><td>automatisch</td></tr><tr><td><strong>Paketübersicht</strong></td><td>Alle Flights mit Callsign, Typ, Auftrag, Frequenz, Startzeit.</td><td>automatisch</td></tr><tr><td><strong>Paket-Tabelle</strong></td><td>Jeder Flight als Block mit Aufgaben, Funk, T/O–Push–TOT–Land und allen Mitgliedern.</td><td>automatisch</td></tr><tr><td><strong>Bedrohungen</strong></td><td>Alle für das Paket freigegebenen Threats mit System, Reichweite, Bullseye.</td><td>automatisch</td></tr><tr><td><strong>Lagekarte</strong></td><td>Alle Routen, Grafiken und freigegebenen Threats auf einer Karte.</td><td>automatisch</td></tr><tr><td><strong>Wetter</strong></td><td>METAR je Flugplatz, Wind in der Höhe, QNH, Wolken.</td><td>automatisch</td></tr><tr><td><strong>Kartenausschnitte</strong></td><td>Eigene Kartenseiten, frei gewählt, gedreht, mit Ebenen.</td><td></td></tr><tr><td><strong>Freie Seite</strong></td><td>Leer, mit eigener Überschrift.</td><td></td></tr></tbody></table><p>„Automatisch“ heißt: Shardwing füllt die Seite aus der Mission und aktualisiert sie bei jeder Änderung.</p><h2 id="seiten-bearbeiten" tabindex="-1">Seiten bearbeiten <a class="header-anchor" href="#seiten-bearbeiten" aria-label="Permalink to &quot;Seiten bearbeiten&quot;">​</a></h2><ul><li><strong>Textabschnitte, Tabellen und Bilder</strong> hinzufügen; Abschnitte lassen sich aufklappen, bearbeiten und löschen.</li><li><strong>Reihenfolge</strong> – am Griff ⋮⋮ in der Liste ziehen.</li><li><strong>Kneeboard von</strong> – alle Flugzeuge oder nur bestimmte Typen.</li><li><strong>Nachtmodus</strong> – dunkle Seiten mit Bernstein-Schrift für alle Seiten. Bei einer Nachtmission schlägt Shardwing ihn einmal vor.</li></ul><p>Jede Seite hat dieselben Ausgaben wie die Lineup Card: <strong>In .miz einbetten</strong>, <strong>PNG</strong>, <strong>PDF</strong>, <strong>Drucken</strong>.</p><h2 id="comm-plan" tabindex="-1">Comm Plan <a class="header-anchor" href="#comm-plan" aria-label="Permalink to &quot;Comm Plan&quot;">​</a></h2><p>Der Comm Plan ist der Funkplan für das ganze Paket – oben links in der Liste.</p><p><img src="'+s+'" alt="Comm Plan mit Stationen, Preset-Kanälen und Vorschau" loading="lazy"></p><p><strong>Stationen</strong> – jedes Netz mit Name, <strong>Art</strong>, Zweck, UHF- und VHF-Frequenz. Die Art bestimmt die Farbe auf der Comm Card:</p><p>Flight intern · Paket/Strike · C2/AWACS · Tanker · JTAC/CAS · ATC/Platz · Guard/Notfall</p><p>Ohne Auswahl rät Shardwing die Art aus dem Namen.</p><p><strong>Frequenzen vorschlagen</strong> füllt leere Felder: AWACS und Tanker aus den KI-Flights, Tower vom Startplatz, sonst freie Frequenzen – auch VHF für Inter-Flight.</p><p><strong>Gruppenfrequenzen verteilen</strong> (nur Designer) gibt jedem Spieler-Flight eine eigene <a href="./flights#units-funk">Gruppenfrequenz</a> in der Mission, frei von den Netzen des Comm Plans.</p><p><strong>Preset-Kanäle</strong> – welche Station auf welchem Kanal von COMM1 und COMM2 liegt, im Band nach Wahl. <em>Eigener Flight</em> setzt automatisch die Gruppenfrequenz jedes Flights ein.</p><p><strong>In die Cartridges</strong> – Die Flights übernehmen den Comm Plan in ihre Cartridge. Hat ein Flight noch keine, legt Shardwing eine aus Route und Funk an. Abweichungen zeigt die <a href="./uebersicht">Übersicht</a> als Prüfung.</p><p>Auf der <strong>Comm Card</strong> jedes Flights erscheinen dann die Kanäle mit Namen und Farben der Netze – und darunter, was nicht im Preset liegt und nachgedreht werden muss.</p>',21)])])}const p=t(d,[["render",o]]);export{b as __pageData,p as default};
